package utez.edu.mx.prestamos_utez.controller;

import javafx.beans.binding.Bindings;
import javafx.event.ActionEvent;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.fxml.Initializable;
import javafx.geometry.Pos;
import javafx.scene.Node;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.control.cell.PropertyValueFactory;
import javafx.scene.image.ImageView;
import javafx.scene.layout.HBox;
import javafx.stage.Modality;
import javafx.stage.Stage;
import utez.edu.mx.prestamos_utez.dao.IProfesorDao;
import utez.edu.mx.prestamos_utez.dao.impl.ProfesorImplDao;
import utez.edu.mx.prestamos_utez.model.Profesor;
import utez.edu.mx.prestamos_utez.sesion.AdministradorSesion;

import java.io.IOException;
import java.net.URL;
import java.util.List;
import java.util.ResourceBundle;

public class ProfesorListController implements Initializable {

    @FXML private TableView<Profesor> tablaProfesores;
    @FXML private TableColumn<Profesor, Number> colNo;
    @FXML private TableColumn<Profesor, String> colNombre;
    @FXML private TableColumn<Profesor, String> colApellidos;
    @FXML private TableColumn<Profesor, String> colDivision;
    @FXML private TableColumn<Profesor, Void> colAcciones;
    @FXML private Button btnAgregarProfesor;
    @FXML private Button btnCerrarSesion;

    @Override
    public void initialize(URL url, ResourceBundle resourceBundle) {
        colNo.setCellValueFactory(cd ->
                Bindings.createIntegerBinding(() ->
                        tablaProfesores.getItems().indexOf(cd.getValue()) + 1
                )
        );
        colNombre.setCellValueFactory(new PropertyValueFactory<>("nombre"));
        colApellidos.setCellValueFactory(new PropertyValueFactory<>("apellidos"));
        colDivision.setCellValueFactory(new PropertyValueFactory<>("division"));

        cargarProfesores();
        configurarColumnaAcciones();

        btnAgregarProfesor.setOnAction(e -> abrirFormularioCrear());
    }
    @FXML
    private void abrirHistorial() {
        try {
            FXMLLoader fx = new FXMLLoader(getClass().getResource(
                    "/utez/edu/mx/prestamos_utez/view/historial_list.fxml"));
            Parent root = fx.load();

            Stage st = new Stage();
            st.setTitle("Historial de préstamos");
            st.setScene(new Scene(root));
            st.setMaximized(true); // si quieres pantalla completa
            st.show();
        } catch (Exception e) { e.printStackTrace(); }
    }

    @FXML
    private void onCerrarSesion(javafx.event.ActionEvent e) {
        try {
            FXMLLoader fx = new FXMLLoader(getClass().getResource(
                    "/utez/edu/mx/prestamos_utez/view/cerrar_sesion.fxml"));
            Parent root = fx.load();

            CerrarSesionController ctrl = fx.getController();

            Stage owner  = (Stage) ((javafx.scene.Node) e.getSource()).getScene().getWindow();
            Stage dialog = new Stage();
            dialog.initOwner(owner);
            dialog.initModality(Modality.WINDOW_MODAL);
            dialog.setTitle("Cerrar sesión");
            dialog.setScene(new Scene(root));

            ctrl.configure(owner, dialog);   // pásale owner y dialog

            dialog.showAndWait();
        } catch (Exception ex) {
            ex.printStackTrace(); // si hay error cargando el FXML, lo verás aquí
        }
    }


    public void cargarProfesores() {
        IProfesorDao dao = new ProfesorImplDao();
        List<Profesor> lista = dao.obtenerTodos();
        tablaProfesores.getItems().setAll(lista);
    }

    private void abrirFormularioCrear() {
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource(
                    "/utez/edu/mx/prestamos_utez/view/profesor_form.fxml"));
            Parent root = loader.load();

            ProfesorFormController form = loader.getController();
            form.setProfesorListController(this);  // para refrescar al cerrar

            Stage stage = new Stage();
            stage.setTitle("Agregar Profesor");
            stage.setScene(new Scene(root));
            stage.initModality(Modality.APPLICATION_MODAL);
            stage.showAndWait();
        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }

    private void editarProfesor(Profesor profesor) {
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource(
                    "/utez/edu/mx/prestamos_utez/view/profesor_form.fxml"));
            Parent root = loader.load();

            ProfesorFormController form = loader.getController();
            form.setProfesorListController(this);
            form.setProfesorAEditar(profesor); // <<< modo edición

            Stage stage = new Stage();
            stage.setTitle("Editar Profesor");
            stage.setScene(new Scene(root));
            stage.initModality(Modality.APPLICATION_MODAL);
            stage.showAndWait();
        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }

    private void borrarProfesor(Profesor profesor) {
        Alert alert = new Alert(Alert.AlertType.CONFIRMATION);
        alert.setTitle("Eliminar profesor");
        alert.setHeaderText(null);
        alert.setContentText("¿Seguro que deseas eliminar a " + profesor.getNombre() + "?");

        alert.showAndWait().ifPresent(btn -> {
            if (btn == ButtonType.OK) {
                IProfesorDao dao = new ProfesorImplDao();
                boolean ok = dao.deleteById(profesor.getId());
                if (ok) {
                    cargarProfesores();
                } else {
                    new Alert(Alert.AlertType.ERROR,
                            "No se pudo eliminar.").showAndWait();
                }
            }
        });
    }



    private void configurarColumnaAcciones() {
        colAcciones.setCellFactory(param -> new TableCell<>() {
            private final Button btnEditar = new Button();
            private final Button btnBorrar = new Button();
            private final HBox box = new HBox(12, btnEditar, btnBorrar);

            {
                // OJO con la ruta: los iconos deben existir en resources/utez/edu/mx/prestamos_utez/icons/
                ImageView editIcon = new ImageView(
                        getClass().getResource("/utez/edu/mx/prestamos_utez/icons/editar.png").toExternalForm());
                editIcon.setFitHeight(18);
                editIcon.setFitWidth(18);
                btnEditar.setGraphic(editIcon);
                btnEditar.setStyle("-fx-background-color: transparent;");
                btnEditar.setOnAction(e -> {
                    Profesor p = getTableView().getItems().get(getIndex());
                    editarProfesor(p);
                });

                ImageView deleteIcon = new ImageView(
                        getClass().getResource("/utez/edu/mx/prestamos_utez/icons/eliminar.png").toExternalForm());
                deleteIcon.setFitHeight(18);
                deleteIcon.setFitWidth(18);
                btnBorrar.setGraphic(deleteIcon);
                btnBorrar.setStyle("-fx-background-color: transparent;");
                btnBorrar.setOnAction(e -> {
                    Profesor p = getTableView().getItems().get(getIndex());
                    borrarProfesor(p);
                });

                box.setAlignment(Pos.CENTER_LEFT);
            }

            @Override
            protected void updateItem(Void item, boolean empty) {
                super.updateItem(item, empty);
                setGraphic(empty ? null : box);
            }
        });
    }
}

package utez.edu.mx.prestamos_utez.controller;

import javafx.beans.binding.Bindings;
import javafx.event.ActionEvent;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.fxml.Initializable;
import javafx.geometry.Pos;
import javafx.scene.Node;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.control.cell.PropertyValueFactory;
import javafx.scene.image.ImageView;
import javafx.scene.layout.HBox;
import javafx.stage.Modality;
import javafx.stage.Stage;
import utez.edu.mx.prestamos_utez.dao.IProfesorDao;
import utez.edu.mx.prestamos_utez.dao.impl.ProfesorImplDao;
import utez.edu.mx.prestamos_utez.model.Profesor;
import utez.edu.mx.prestamos_utez.sesion.AdministradorSesion;

import java.io.IOException;
import java.net.URL;
import java.util.List;
import java.util.ResourceBundle;

public class ProfesorListController implements Initializable {

    @FXML private TableView<Profesor> tablaProfesores;
    @FXML private TableColumn<Profesor, Number> colNo;
    @FXML private TableColumn<Profesor, String> colNombre;
    @FXML private TableColumn<Profesor, String> colApellidos;
    @FXML private TableColumn<Profesor, String> colDivision;
    @FXML private TableColumn<Profesor, Void> colAcciones;
    @FXML private Button btnAgregarProfesor;
    @FXML private Button btnCerrarSesion;

    @Override
    public void initialize(URL url, ResourceBundle resourceBundle) {
        colNo.setCellValueFactory(cd ->
                Bindings.createIntegerBinding(() ->
                        tablaProfesores.getItems().indexOf(cd.getValue()) + 1
                )
        );
        colNombre.setCellValueFactory(new PropertyValueFactory<>("nombre"));
        colApellidos.setCellValueFactory(new PropertyValueFactory<>("apellidos"));
        colDivision.setCellValueFactory(new PropertyValueFactory<>("division"));

        cargarProfesores();
        configurarColumnaAcciones();

        btnAgregarProfesor.setOnAction(e -> abrirFormularioCrear());
    }
    @FXML
    private void abrirHistorial() {
        try {
            FXMLLoader fx = new FXMLLoader(getClass().getResource(
                    "/utez/edu/mx/prestamos_utez/view/historial_list.fxml"));
            Parent root = fx.load();

            Stage st = new Stage();
            st.setTitle("Historial de préstamos");
            st.setScene(new Scene(root));
            st.setMaximized(true); // si quieres pantalla completa
            st.show();
        } catch (Exception e) { e.printStackTrace(); }
    }

    @FXML
    private void onCerrarSesion(javafx.event.ActionEvent e) {
        try {
            FXMLLoader fx = new FXMLLoader(getClass().getResource(
                    "/utez/edu/mx/prestamos_utez/view/cerrar_sesion.fxml"));
            Parent root = fx.load();

            CerrarSesionController ctrl = fx.getController();

            Stage owner  = (Stage) ((javafx.scene.Node) e.getSource()).getScene().getWindow();
            Stage dialog = new Stage();
            dialog.initOwner(owner);
            dialog.initModality(Modality.WINDOW_MODAL);
            dialog.setTitle("Cerrar sesión");
            dialog.setScene(new Scene(root));

            ctrl.configure(owner, dialog);   // pásale owner y dialog

            dialog.showAndWait();
        } catch (Exception ex) {
            ex.printStackTrace(); // si hay error cargando el FXML, lo verás aquí
        }
    }


    public void cargarProfesores() {
        IProfesorDao dao = new ProfesorImplDao();
        var usuario = AdministradorSesion.getUsuarioActual();
        if (usuario != null && "Encargado".equalsIgnoreCase(usuario.getNombreRol()) && usuario.getNombreDivision() != null) {
            // Filtrar por división del encargado
            // Aquí necesitas el id de la división, ajusta si tienes el id
            // Si solo tienes el nombre, deberías obtener el id por nombre
            // Supongamos que tienes el id en usuario.getIdDivision()
            List<Profesor> lista = ((ProfesorImplDao)dao).obtenerPorDivision(usuario.getIdDivision());
            tablaProfesores.getItems().setAll(lista);
        } else {
            List<Profesor> lista = dao.obtenerTodos();
            tablaProfesores.getItems().setAll(lista);
        }
    }

    private void abrirFormularioCrear() {
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource(
                    "/utez/edu/mx/prestamos_utez/view/profesor_form.fxml"));
            Parent root = loader.load();

            ProfesorFormController form = loader.getController();
            form.setProfesorListController(this);  // para refrescar al cerrar

            Stage stage = new Stage();
            stage.setTitle("Agregar Profesor");
            stage.setScene(new Scene(root));
            stage.initModality(Modality.APPLICATION_MODAL);
            stage.showAndWait();
        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }

    private void editarProfesor(Profesor profesor) {
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource(
                    "/utez/edu/mx/prestamos_utez/view/profesor_form.fxml"));
            Parent root = loader.load();

            ProfesorFormController form = loader.getController();
            form.setProfesorListController(this);
            form.setProfesorAEditar(profesor); // <<< modo edición

            Stage stage = new Stage();
            stage.setTitle("Editar Profesor");
            stage.setScene(new Scene(root));
            stage.initModality(Modality.APPLICATION_MODAL);
            stage.showAndWait();
        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }

    private void borrarProfesor(Profesor profesor) {
        Alert alert = new Alert(Alert.AlertType.CONFIRMATION);
        alert.setTitle("Eliminar profesor");
        alert.setHeaderText(null);
        alert.setContentText("¿Seguro que deseas eliminar a " + profesor.getNombre() + "?");

        alert.showAndWait().ifPresent(btn -> {
            if (btn == ButtonType.OK) {
                IProfesorDao dao = new ProfesorImplDao();
                boolean ok = dao.deleteById(profesor.getId());
                if (ok) {
                    cargarProfesores();
                } else {
                    new Alert(Alert.AlertType.ERROR,
                            "No se pudo eliminar.").showAndWait();
                }
            }
        });
    }



    private void configurarColumnaAcciones() {
        colAcciones.setCellFactory(param -> new TableCell<>() {
            private final Button btnEditar = new Button();
            private final Button btnBorrar = new Button();
            private final HBox box = new HBox(12, btnEditar, btnBorrar);

            {
                // OJO con la ruta: los iconos deben existir en resources/utez/edu/mx/prestamos_utez/icons/
                ImageView editIcon = new ImageView(
                        getClass().getResource("/utez/edu/mx/prestamos_utez/icons/editar.png").toExternalForm());
                editIcon.setFitHeight(18);
                editIcon.setFitWidth(18);
                btnEditar.setGraphic(editIcon);
                btnEditar.setStyle("-fx-background-color: transparent;");
                btnEditar.setOnAction(e -> {
                    Profesor p = getTableView().getItems().get(getIndex());
                    editarProfesor(p);
                });

                ImageView deleteIcon = new ImageView(
                        getClass().getResource("/utez/edu/mx/prestamos_utez/icons/eliminar.png").toExternalForm());
                deleteIcon.setFitHeight(18);
                deleteIcon.setFitWidth(18);
                btnBorrar.setGraphic(deleteIcon);
                btnBorrar.setStyle("-fx-background-color: transparent;");
                btnBorrar.setOnAction(e -> {
                    Profesor p = getTableView().getItems().get(getIndex());
                    borrarProfesor(p);
                });

                box.setAlignment(Pos.CENTER_LEFT);
            }

            @Override
            protected void updateItem(Void item, boolean empty) {
                super.updateItem(item, empty);
                setGraphic(empty ? null : box);
            }
        });
    }
}

package utez.edu.mx.prestamos_utez.controller;

import javafx.collections.FXCollections;
import javafx.fxml.FXML;
import javafx.scene.control.*;
import javafx.stage.Stage;
import utez.edu.mx.prestamos_utez.config.DBConnection;

import java.sql.*;
import java.util.LinkedHashMap;
import java.util.Map;

public class UsuarioFormController {

    @FXML private TextField txtNombre;
    @FXML private TextField txtApellidos;
    @FXML private TextField txtCorreo;
    @FXML private ComboBox<String> cmbRol; // mostramos nombre del rol
    @FXML private PasswordField txtPass;
    @FXML private Label lblDivision;
    @FXML private ComboBox<String> cmbDivision;

    // Mapa nombreRol -> idRol para el ComboBox
    private final Map<String, Integer> rolMap = new LinkedHashMap<>();

    private Integer editIdUsuario = null; // si es null = crear; si no, editar
    private Runnable onSaved;             // callback para refrescar lista

    public void initialize() {
        cargarRoles();
        cmbRol.valueProperty().addListener((obs, old, nuevo) -> {
            boolean esEncargado = "Encargado".equals(nuevo);
            lblDivision.setVisible(esEncargado);
            lblDivision.setManaged(esEncargado);
            cmbDivision.setVisible(esEncargado);
            cmbDivision.setManaged(esEncargado);
            if (esEncargado) {
                cargarDivisiones();
            } else {
                cmbDivision.getItems().clear();
            }
        });
    }

    /** Llamar esto antes de mostrar el form si vas a EDITAR */
    public void setUsuario(Integer idUsuario, String nombre, String apellidos, String correo,
                           Integer idRol, String nombreRol, Runnable onSaved) {
        this.editIdUsuario = idUsuario;
        this.onSaved = onSaved;

        if (idUsuario != null) {
            txtNombre.setText(nombre);
            txtApellidos.setText(apellidos);
            txtCorreo.setText(correo);
            // Seleccionar el rol por nombre si nos lo pasan
            if (nombreRol != null) {
                cmbRol.setValue(nombreRol);
            } else if (idRol != null) {
                // Si no vino el nombre, intenta seleccionar por idRol
                rolMap.forEach((nom, id) -> { if (id.equals(idRol)) cmbRol.setValue(nom); });
            }
            // Contraseña: se deja vacía; si la llenas, se actualiza
        } else {
            // crear
            cmbRol.getSelectionModel().clearSelection();
        }
    }

    private void cargarDivisiones() {
        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement("SELECT NOMBRE FROM DIVISION ORDER BY NOMBRE ASC");
             ResultSet rs = ps.executeQuery()) {
            var lista = FXCollections.<String>observableArrayList();
            while (rs.next()) {
                lista.add(rs.getString("NOMBRE"));
            }
            cmbDivision.setItems(lista);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @FXML
    private void cancelar() {
        ((Stage) txtNombre.getScene().getWindow()).close();
    }

    @FXML
    private void guardar() {
        // Validaciones básicas
        if (txtNombre.getText().isBlank() || txtApellidos.getText().isBlank()
                || txtCorreo.getText().isBlank() || cmbRol.getValue() == null) {
            alerta(Alert.AlertType.WARNING, "Completa nombre, apellidos, correo y rol.");
            return;
        }

        String nombre = txtNombre.getText().trim();
        String apellidos = txtApellidos.getText().trim();
        String correo = txtCorreo.getText().trim();
        Integer idRol = rolMap.get(cmbRol.getValue());
        String pass = txtPass.getText(); // si vacío en editar, no se actualiza

        if ("Encargado".equals(cmbRol.getValue())) {
            if (cmbDivision.getValue() == null || cmbDivision.getValue().isEmpty()) {
                new Alert(Alert.AlertType.ERROR, "Debes seleccionar la división para el encargado.").showAndWait();
                return;
            }
        }

        try (Connection con = DBConnection.getConnection()) {
            if (editIdUsuario == null) {
                // CREAR
                if (pass == null || pass.isBlank()) {
                    alerta(Alert.AlertType.WARNING, "Define una contraseña para el nuevo usuario.");
                    return;
                }
                // Cambia USUARIO_SEQ por el nombre de tu secuencia si aplica
                String sql = """
                    INSERT INTO USUARIO (ID_USUARIO, NOMBRE, APELLIDOS, CORREO, CONTRASENA, ID_ROL)
                    VALUES (USUARIO_SEQ.NEXTVAL, ?, ?, ?, ?, ?)
                """;
                try (PreparedStatement ps = con.prepareStatement(sql)) {
                    ps.setString(1, nombre);
                    ps.setString(2, apellidos);
                    ps.setString(3, correo);
                    ps.setString(4, pass);
                    ps.setInt(5, idRol);
                    int n = ps.executeUpdate();
                    if (n == 1) {
                        notiOk("Usuario creado.");
                        if (onSaved != null) onSaved.run();
                        cancelar();
                    } else alerta(Alert.AlertType.ERROR, "No se pudo crear el usuario.");
                }
            } else {
                // EDITAR
                String sqlSinPass = """
                    UPDATE USUARIO
                    SET NOMBRE=?, APELLIDOS=?, CORREO=?, ID_ROL=?
                    WHERE ID_USUARIO=?
                """;
                String sqlConPass = """
                    UPDATE USUARIO
                    SET NOMBRE=?, APELLIDOS=?, CORREO=?, ID_ROL=?, CONTRASENA=?
                    WHERE ID_USUARIO=?
                """;
                if (pass == null || pass.isBlank()) {
                    try (PreparedStatement ps = con.prepareStatement(sqlSinPass)) {
                        ps.setString(1, nombre);
                        ps.setString(2, apellidos);
                        ps.setString(3, correo);
                        ps.setInt(4, idRol);
                        ps.setInt(5, editIdUsuario);
                        int n = ps.executeUpdate();
                        if (n == 1) {
                            notiOk("Usuario actualizado.");
                            if (onSaved != null) onSaved.run();
                            cancelar();
                        } else alerta(Alert.AlertType.ERROR, "No se pudo actualizar el usuario.");
                    }
                } else {
                    try (PreparedStatement ps = con.prepareStatement(sqlConPass)) {
                        ps.setString(1, nombre);
                        ps.setString(2, apellidos);
                        ps.setString(3, correo);
                        ps.setInt(4, idRol);
                        ps.setString(5, pass);
                        ps.setInt(6, editIdUsuario);
                        int n = ps.executeUpdate();
                        if (n == 1) {
                            notiOk("Usuario actualizado (con contraseña).");
                            if (onSaved != null) onSaved.run();
                            cancelar();
                        } else alerta(Alert.AlertType.ERROR, "No se pudo actualizar el usuario.");
                    }
                }
            }
        } catch (SQLException e) {
            e.printStackTrace();
            alerta(Alert.AlertType.ERROR, "Error SQL: " + e.getMessage());
        }
    }

    private void cargarRoles() {
        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(
                     "SELECT ID_ROL, NOMBRE_ROL FROM ROL ORDER BY ID_ROL");
             ResultSet rs = ps.executeQuery()) {
            rolMap.clear();
            while (rs.next()) {
                rolMap.put(rs.getString("NOMBRE_ROL"), rs.getInt("ID_ROL"));
            }
            cmbRol.setItems(javafx.collections.FXCollections
                    .observableArrayList(rolMap.keySet()));
        } catch (SQLException e) {
            e.printStackTrace();
            new Alert(Alert.AlertType.ERROR,
                    "No se pudieron cargar los roles: " + e.getMessage()).showAndWait();
        }
    }



    private void alerta(Alert.AlertType t, String msg) {
        new Alert(t, msg, ButtonType.OK).showAndWait();
    }
    private void notiOk(String msg) { alerta(Alert.AlertType.INFORMATION, msg); }
}

package utez.edu.mx.prestamos_utez.controller;

import javafx.collections.FXCollections;
import javafx.fxml.FXML;
import javafx.scene.control.*;
import javafx.stage.Stage;
import utez.edu.mx.prestamos_utez.config.DBConnection;

import java.sql.*;
import java.util.LinkedHashMap;
import java.util.Map;

public class UsuarioFormController {

    @FXML private TextField txtNombre;
    @FXML private TextField txtApellidos;
    @FXML private TextField txtCorreo;
    @FXML private ComboBox<String> cmbRol; // mostramos nombre del rol
    @FXML private PasswordField txtPass;
    @FXML private Label lblDivision;
    @FXML private ComboBox<String> cmbDivision;

    // Mapa nombreRol -> idRol para el ComboBox
    private final Map<String, Integer> rolMap = new LinkedHashMap<>();
    private final Map<String, Integer> divisionMap = new LinkedHashMap<>(); // nombre -> id

    private Integer editIdUsuario = null; // si es null = crear; si no, editar
    private Runnable onSaved;             // callback para refrescar lista

    public void initialize() {
        cargarRoles();
        cmbRol.valueProperty().addListener((obs, old, nuevo) -> {
            boolean esEncargado = "Encargado".equals(nuevo);
            lblDivision.setVisible(esEncargado);
            lblDivision.setManaged(esEncargado);
            cmbDivision.setVisible(esEncargado);
            cmbDivision.setManaged(esEncargado);
            if (esEncargado) {
                cargarDivisiones();
            } else {
                cmbDivision.getItems().clear();
            }
        });
    }

    /** Llamar esto antes de mostrar el form si vas a EDITAR */
    public void setUsuario(Integer idUsuario, String nombre, String apellidos, String correo,
                           Integer idRol, String nombreRol, Runnable onSaved) {
        this.editIdUsuario = idUsuario;
        this.onSaved = onSaved;

        if (idUsuario != null) {
            txtNombre.setText(nombre);
            txtApellidos.setText(apellidos);
            txtCorreo.setText(correo);
            // Seleccionar el rol por nombre si nos lo pasan
            if (nombreRol != null) {
                cmbRol.setValue(nombreRol);
            } else if (idRol != null) {
                // Si no vino el nombre, intenta seleccionar por idRol
                rolMap.forEach((nom, id) -> { if (id.equals(idRol)) cmbRol.setValue(nom); });
            }
            // Contraseña: se deja vacía; si la llenas, se actualiza
        } else {
            // crear
            cmbRol.getSelectionModel().clearSelection();
        }
    }

    private void cargarDivisiones() {
        divisionMap.clear();
        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement("SELECT ID_DIVISION, NOMBRE FROM DIVISION ORDER BY NOMBRE ASC");
             ResultSet rs = ps.executeQuery()) {
            var lista = FXCollections.<String>observableArrayList();
            while (rs.next()) {
                divisionMap.put(rs.getString("NOMBRE"), rs.getInt("ID_DIVISION"));
                lista.add(rs.getString("NOMBRE"));
            }
            cmbDivision.setItems(lista);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @FXML
    private void cancelar() {
        ((Stage) txtNombre.getScene().getWindow()).close();
    }

    @FXML
    private void guardar() {
        // Validaciones básicas
        if (txtNombre.getText().isBlank() || txtApellidos.getText().isBlank()
                || txtCorreo.getText().isBlank() || cmbRol.getValue() == null) {
            alerta(Alert.AlertType.WARNING, "Completa nombre, apellidos, correo y rol.");
            return;
        }

        String nombre = txtNombre.getText().trim();
        String apellidos = txtApellidos.getText().trim();
        String correo = txtCorreo.getText().trim();
        Integer idRol = rolMap.get(cmbRol.getValue());
        String pass = txtPass.getText(); // si vacío en editar, no se actualiza

        Integer idDivision = null;
        if ("Encargado".equals(cmbRol.getValue())) {
            if (cmbDivision.getValue() == null || cmbDivision.getValue().isEmpty()) {
                new Alert(Alert.AlertType.ERROR, "Debes seleccionar la división para el encargado.").showAndWait();
                return;
            }
            idDivision = divisionMap.get(cmbDivision.getValue());
        }

        try (Connection con = DBConnection.getConnection()) {
            if (editIdUsuario == null) {
                // CREAR
                if (pass == null || pass.isBlank()) {
                    alerta(Alert.AlertType.WARNING, "Define una contraseña para el nuevo usuario.");
                    return;
                }
                String sql = """
                    INSERT INTO USUARIO (ID_USUARIO, NOMBRE, APELLIDOS, CORREO, CONTRASENA, ID_ROL, ID_DIVISION)
                    VALUES (USUARIO_SEQ.NEXTVAL, ?, ?, ?, ?, ?, ?)
                """;
                try (PreparedStatement ps = con.prepareStatement(sql)) {
                    ps.setString(1, nombre);
                    ps.setString(2, apellidos);
                    ps.setString(3, correo);
                    ps.setString(4, pass);
                    ps.setInt(5, idRol);
                    if (idDivision != null) {
                        ps.setInt(6, idDivision);
                    } else {
                        ps.setNull(6, java.sql.Types.INTEGER);
                    }
                    int n = ps.executeUpdate();
                    if (n == 1) {
                        notiOk("Usuario creado.");
                        if (onSaved != null) onSaved.run();
                        cancelar();
                    } else alerta(Alert.AlertType.ERROR, "No se pudo crear el usuario.");
                }
            } else {
                // EDITAR
                String sqlSinPass = """
                    UPDATE USUARIO
                    SET NOMBRE=?, APELLIDOS=?, CORREO=?, ID_ROL=?, ID_DIVISION=?
                    WHERE ID_USUARIO=?
                """;
                String sqlConPass = """
                    UPDATE USUARIO
                    SET NOMBRE=?, APELLIDOS=?, CORREO=?, ID_ROL=?, CONTRASENA=?, ID_DIVISION=?
                    WHERE ID_USUARIO=?
                """;
                if (pass == null || pass.isBlank()) {
                    try (PreparedStatement ps = con.prepareStatement(sqlSinPass)) {
                        ps.setString(1, nombre);
                        ps.setString(2, apellidos);
                        ps.setString(3, correo);
                        ps.setInt(4, idRol);
                        if (idDivision != null) {
                            ps.setInt(5, idDivision);
                        } else {
                            ps.setNull(5, java.sql.Types.INTEGER);
                        }
                        ps.setInt(6, editIdUsuario);
                        int n = ps.executeUpdate();
                        if (n == 1) {
                            notiOk("Usuario actualizado.");
                            if (onSaved != null) onSaved.run();
                            cancelar();
                        } else alerta(Alert.AlertType.ERROR, "No se pudo actualizar el usuario.");
                    }
                } else {
                    try (PreparedStatement ps = con.prepareStatement(sqlConPass)) {
                        ps.setString(1, nombre);
                        ps.setString(2, apellidos);
                        ps.setString(3, correo);
                        ps.setInt(4, idRol);
                        ps.setString(5, pass);
                        if (idDivision != null) {
                            ps.setInt(6, idDivision);
                        } else {
                            ps.setNull(6, java.sql.Types.INTEGER);
                        }
                        ps.setInt(7, editIdUsuario);
                        int n = ps.executeUpdate();
                        if (n == 1) {
                            notiOk("Usuario actualizado (con contraseña).");
                            if (onSaved != null) onSaved.run();
                            cancelar();
                        } else alerta(Alert.AlertType.ERROR, "No se pudo actualizar el usuario.");
                    }
                }
            }
        } catch (SQLException e) {
            e.printStackTrace();
            alerta(Alert.AlertType.ERROR, "Error SQL: " + e.getMessage());
        }
    }

    private void cargarRoles() {
        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(
                     "SELECT ID_ROL, NOMBRE_ROL FROM ROL ORDER BY ID_ROL");
             ResultSet rs = ps.executeQuery()) {
            rolMap.clear();
            while (rs.next()) {
                rolMap.put(rs.getString("NOMBRE_ROL"), rs.getInt("ID_ROL"));
            }
            cmbRol.setItems(javafx.collections.FXCollections
                    .observableArrayList(rolMap.keySet()));
        } catch (SQLException e) {
            e.printStackTrace();
            new Alert(Alert.AlertType.ERROR,
                    "No se pudieron cargar los roles: " + e.getMessage()).showAndWait();
        }
    }



    private void alerta(Alert.AlertType t, String msg) {
        new Alert(t, msg, ButtonType.OK).showAndWait();
    }
    private void notiOk(String msg) { alerta(Alert.AlertType.INFORMATION, msg); }
}

