package utez.edu.mx.prestamos_utez.dao;

import utez.edu.mx.prestamos_utez.model.Objeto;
import java.util.List;

public interface IObjetoDao {
    List<Objeto> obtenerTodos();
    boolean create(Objeto objeto);
    boolean update(Objeto objeto);
    List<Objeto> obtenerPorDivision(int idDivision);
}

package utez.edu.mx.prestamos_utez.dao.impl;

import utez.edu.mx.prestamos_utez.config.DBConnection;
import utez.edu.mx.prestamos_utez.dao.IUsuarioDao;
import utez.edu.mx.prestamos_utez.model.Rol;
import utez.edu.mx.prestamos_utez.model.Usuario;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class UsuarioImplDao implements IUsuarioDao {

    @Override
    public Usuario login(String correo, String pass) throws SQLException {
        String sql = """
            SELECT ID_USUARIO, NOMBRE, APELLIDOS, CORREO, ID_ROL
            FROM USUARIO
            WHERE CORREO = ? AND CONTRASENA = ?
        """;

        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sql)) {

            ps.setString(1, correo);
            ps.setString(2, pass);

            try (ResultSet rs = ps.executeQuery()) {
                if (!rs.next()) return null;

                Usuario u = new Usuario();
                u.setIdUsuario(rs.getInt("ID_USUARIO"));
                u.setNombre(rs.getString("NOMBRE"));
                u.setApellidos(rs.getString("APELLIDOS"));
                u.setCorreo(rs.getString("CORREO"));
                u.setIdRol(rs.getInt("ID_ROL")); // <-- NUMBER -> int
                return u;
            }
        }
    }

    @Override
    public List<Rol> listarRoles() throws SQLException {
        String sql = "SELECT ID_ROL, NOMBRE_ROL FROM ROL ORDER BY ID_ROL";
        List<Rol> roles = new ArrayList<>();

        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {

            while (rs.next()) {
                roles.add(new Rol(
                        rs.getInt("ID_ROL"),
                        rs.getString("NOMBRE_ROL")
                ));
            }
        }
        return roles;
    }
}

package utez.edu.mx.prestamos_utez.dao.impl;

import utez.edu.mx.prestamos_utez.config.DBConnection;
import utez.edu.mx.prestamos_utez.dao.IUsuarioDao;
import utez.edu.mx.prestamos_utez.model.Rol;
import utez.edu.mx.prestamos_utez.model.Usuario;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class UsuarioImplDao implements IUsuarioDao {

    @Override
    public Usuario login(String correo, String pass) throws SQLException {
        String sql = """
            SELECT u.ID_USUARIO, u.NOMBRE, u.APELLIDOS, u.CORREO, u.ID_ROL, r.NOMBRE_ROL, d.ID_DIVISION, d.NOMBRE AS NOMBRE_DIVISION
            FROM USUARIO u
            JOIN ROL r ON u.ID_ROL = r.ID_ROL
            LEFT JOIN DIVISION d ON u.ID_DIVISION = d.ID_DIVISION
            WHERE u.CORREO = ? AND u.CONTRASENA = ?
        """;

        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sql)) {

            ps.setString(1, correo);
            ps.setString(2, pass);

            try (ResultSet rs = ps.executeQuery()) {
                if (!rs.next()) return null;

                Usuario u = new Usuario();
                u.setIdUsuario(rs.getInt("ID_USUARIO"));
                u.setNombre(rs.getString("NOMBRE"));
                u.setApellidos(rs.getString("APELLIDOS"));
                u.setCorreo(rs.getString("CORREO"));
                u.setIdRol(rs.getInt("ID_ROL"));
                u.setNombreRol(rs.getString("NOMBRE_ROL"));
                u.setIdDivision(rs.getInt("ID_DIVISION"));
                u.setNombreDivision(rs.getString("NOMBRE_DIVISION"));
                return u;
            }
        }
    }

    @Override
    public List<Rol> listarRoles() throws SQLException {
        String sql = "SELECT ID_ROL, NOMBRE_ROL FROM ROL ORDER BY ID_ROL";
        List<Rol> roles = new ArrayList<>();

        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {

            while (rs.next()) {
                roles.add(new Rol(
                        rs.getInt("ID_ROL"),
                        rs.getString("NOMBRE_ROL")
                ));
            }
        }
        return roles;
    }
}

package utez.edu.mx.prestamos_utez.model;

public class Usuario {
    private int idUsuario;      // ID_USUARIO
    private String nombre;      // NOMBRE
    private String apellidos;   // APELLIDOS
    private String correo;      // CORREO (lo usarás como username)
    private String contrasena;  // CONTRASENA (hash)
    private int idRol;          // ID_ROL (FK)
    private String nombreRol;   // (via JOIN para mostrar "ADMIN"/"ENCARGADO")

    public Usuario() {

    }

    public Usuario(int idUsuario, String nombre, String apellidos, String correo, String contrasena, int idRol, String nombreRol) {
        this.idUsuario = idUsuario;
        this.nombre = nombre;
        this.apellidos = apellidos;
        this.correo = correo;
        this.contrasena = contrasena;
        this.idRol = idRol;
        this.nombreRol = nombreRol;
    }

    public int getIdUsuario() {
        return idUsuario;
    }

    public void setIdUsuario(int idUsuario) {
        this.idUsuario = idUsuario;
    }

    public String getNombre() {
        return nombre;
    }

    public void setNombre(String nombre) {
        this.nombre = nombre;
    }

    public String getApellidos() {
        return apellidos;
    }

    public void setApellidos(String apellidos) {
        this.apellidos = apellidos;
    }

    public String getCorreo() {
        return correo;
    }

    public void setCorreo(String correo) {
        this.correo = correo;
    }

    public String getContrasena() {
        return contrasena;
    }

    public void setContrasena(String contrasena) {
        this.contrasena = contrasena;
    }

    public int getIdRol() {
        return idRol;
    }

    public void setIdRol(int idRol) {
        this.idRol = idRol;
    }

    public String getNombreRol() {
        return nombreRol;
    }

    public void setNombreRol(String nombreRol) {
        this.nombreRol = nombreRol;
    }
}

package utez.edu.mx.prestamos_utez.model;

public class Usuario {
    private int idUsuario;      // ID_USUARIO
    private String nombre;      // NOMBRE
    private String apellidos;   // APELLIDOS
    private String correo;      // CORREO (lo usarás como username)
    private String contrasena;  // CONTRASENA (hash)
    private int idRol;          // ID_ROL (FK)
    private String nombreRol;   // (via JOIN para mostrar "ADMIN"/"ENCARGADO")
    private String nombreDivision; // Nombre de la división (puede ser null)
    private int idDivision; // ID_DIVISION (FK)

    public Usuario() {

    }

    public Usuario(int idUsuario, String nombre, String apellidos, String correo, String contrasena, int idRol, String nombreRol, String nombreDivision, int idDivision) {
        this.idUsuario = idUsuario;
        this.nombre = nombre;
        this.apellidos = apellidos;
        this.correo = correo;
        this.contrasena = contrasena;
        this.idRol = idRol;
        this.nombreRol = nombreRol;
        this.nombreDivision = nombreDivision;
        this.idDivision = idDivision;
    }

    public int getIdUsuario() {
        return idUsuario;
    }

    public void setIdUsuario(int idUsuario) {
        this.idUsuario = idUsuario;
    }

    public String getNombre() {
        return nombre;
    }

    public void setNombre(String nombre) {
        this.nombre = nombre;
    }

    public String getApellidos() {
        return apellidos;
    }

    public void setApellidos(String apellidos) {
        this.apellidos = apellidos;
    }

    public String getCorreo() {
        return correo;
    }

    public void setCorreo(String correo) {
        this.correo = correo;
    }

    public String getContrasena() {
        return contrasena;
    }

    public void setContrasena(String contrasena) {
        this.contrasena = contrasena;
    }

    public int getIdRol() {
        return idRol;
    }

    public void setIdRol(int idRol) {
        this.idRol = idRol;
    }

    public String getNombreRol() {
        return nombreRol;
    }

    public void setNombreRol(String nombreRol) {
        this.nombreRol = nombreRol;
    }

    public String getNombreDivision() {
        return nombreDivision;
    }

    public void setNombreDivision(String nombreDivision) {
        this.nombreDivision = nombreDivision;
    }

    public int getIdDivision() {
        return idDivision;
    }

    public void setIdDivision(int idDivision) {
        this.idDivision = idDivision;
    }
}
